import math

def brute_grundy(max_n):
    g = [0] * (max_n + 1)
    for x in range(1, max_n + 1):
        reachable = set()
        for y in range(1, x + 1):
            if math.gcd(x, y) == 1:
                reachable.add(g[x - y])
        # mex
        m = 0
        while m in reachable:
            m += 1
        g[x] = m
    return g

def formula_grundy(max_n):
    # Compute spf
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    g = [0] * (max_n + 1)
    for x in range(1, max_n + 1):
        if x % 2 == 0:
            g[x] = 0
        elif x == 1:
            g[x] = 1
        else:
            g[x] = (spf[x] + 1) // 2
    return g

